const items=()=>tab==='saved'?favorites:lesson[tab];
function render(){if(inlinePlayback&&inlinePlayback.token===playToken&&findGridCard(inlinePlayback.p)){refreshGridStates();return;}const list=items();$('lessonTitle').textContent=lesson.title;$('count').textContent=`${list.length} 张卡片`;$('grid').className='grid'+(tab==='words'?' word-grid':'');$('grid').replaceChildren();for(const [i,p]of list.entries()){const card=document.createElement('div');card.dataset.pinyin=p;card.className='card status-'+readingState(seen.has(p),visibleReview(p),manualMarks[p]);const btn=document.createElement('button');btn.className='sound';btn.setAttribute('aria-label','学习 '+p);const label=document.createElement('span');label.className='pinyin';renderCardPinyin(label,p);const hint=document.createElement('small');const grade=reviewGrade(p,visibleReview(p));hint.textContent=manualMarks[p]==='read'?'✓ 已读':manualMarks[p]==='unknown'?'不会 · 再练练':grade?(reviews[p].passed?'✓ 本次读对':'↻ 还需练习')+' · 家长检查 '+grade.score+' 分':seen.has(p)?'已听 · 未评分':'◖)) 点我听';const glyph=document.createElement('span');glyph.className='card-hanzi';Array.from(linkedWord(p)?.[0]||displayedHanzi(p)).forEach((char,index)=>{const unit=document.createElement('span');unit.className='grid-glyph';unit.dataset.syllable=String(index);unit.textContent=char;glyph.append(unit);});btn.append(label,glyph,hint);btn.onclick=()=>quickMode?quickReadCard(p,btn):openLearn(i);if(quickMode){const detail=document.createElement('button');detail.className='open-details';detail.textContent='展开练习';detail.setAttribute('aria-label','展开 '+p+' 的练习');detail.onclick=()=>openLearn(i);card.append(detail);}const star=document.createElement('button');star.className='star'+(favorites.includes(p)?' on':'');star.textContent=favorites.includes(p)?'★':'☆';star.setAttribute('aria-label','收藏 '+p);star.setAttribute('aria-pressed',String(favorites.includes(p)));star.onclick=()=>{favorites=favorites.includes(p)?favorites.filter(x=>x!==p):[...favorites,p];persist();render();};card.append(btn,star);$('grid').append(card);}if(!list.length){const empty=document.createElement('div');empty.className='empty';empty.textContent=tab==='saved'?'还没有收藏，点卡片右上角的小星星吧。':'还没有练习，上传作业或手动输入吧。';$('grid').append(empty);}$('progress').textContent=`听过 ${list.filter(p=>seen.has(p)).length} / ${list.length} · 家长确认读对 ${list.filter(p=>reviews[p]?.passed).length}`;$('playAll').disabled=!list.length;if($('learn').open){refreshWordStepStates(items()[selected]);syncCharacterColors(items()[selected]);}refreshGridStates();}
function findGridCard(p){return [...$('grid').querySelectorAll('.card')].find(card=>card.dataset.pinyin===p);}
function renderCardPinyin(box,p){p.split(' ').forEach((syllable,i)=>{if(i)box.append(document.createTextNode(' '));const group=document.createElement('span');group.className='pinyin-syllable';group.dataset.syllable=String(i);const parts=details(syllable).parts;if(parts?.length>1)parts.forEach((part,j)=>group.append(soundUnit(part,syllable,j,i,j===0?'initial':'final')));else group.append(soundUnit(syllable,syllable,-1,i,'whole'));box.append(group);});}
function refreshGridStates(){for(const card of $('grid').querySelectorAll('.card')){const p=card.dataset.pinyin,state=readingState(seen.has(p),visibleReview(p),manualMarks[p]);for(const name of ['new','heard','passed','practice','read','unknown'])card.classList.toggle('status-'+name,state===name);const hint=card.querySelector('.sound small'),grade=reviewGrade(p,visibleReview(p));if(hint)hint.textContent=manualMarks[p]==='read'?'✓ 已读':manualMarks[p]==='unknown'?'不会 · 再练练':grade?(reviews[p].passed?'✓ 本次读对':'↻ 还需练习')+' · 家长检查 '+grade.score+' 分':seen.has(p)?'已听 · 未评分':'◖)) 点我听';card.querySelectorAll('.grid-glyph,.pinyin-syllable').forEach(el=>el.classList.toggle('grid-character-heard',hasHeardCharacter(p,Number(el.dataset.syllable))));const star=card.querySelector('.star');if(star){star.classList.toggle('on',favorites.includes(p));star.textContent=favorites.includes(p)?'★':'☆';star.setAttribute('aria-pressed',String(favorites.includes(p)));}}const list=items();$('progress').textContent=`听过 ${list.filter(p=>seen.has(p)).length} / ${list.length} · 家长确认读对 ${list.filter(p=>reviews[p]?.passed).length}`;syncModeControls();}
function inlineFormula(target,p,index){let box=target.querySelector('.inline-formula');if(!box){box=document.createElement('span');box.className='inline-formula';target.append(box);}renderFormula(box,p,index);}
function setTab(t){stopSpeech();tab=t;for(const id of ['syllables','words','saved']){$(id).classList.toggle('selected',id===t);$(id).setAttribute('aria-selected',String(id===t));}render();}
for(const id of ['syllables','words','saved'])$(id).onclick=()=>setTab(id);
function refreshVoices(){if(!('speechSynthesis'in window))return;voiceList=speechSynthesis.getVoices().filter(v=>/^zh[-_](CN|Hans)/i.test(v.lang));if(!voiceList.length)voiceList=speechSynthesis.getVoices().filter(v=>/^zh/i.test(v.lang));const prev=$('voice').value;$('voice').replaceChildren();voiceList.forEach((v,i)=>{const o=document.createElement('option');o.value=i;o.textContent=v.name;$('voice').append(o);});if(!voiceList.length){const o=document.createElement('option');o.textContent='未检测到中文语音，请在系统添加普通话声音';$('voice').append(o);}else if(prev)$('voice').value=prev;}
if('speechSynthesis'in window){speechSynthesis.onvoiceschanged=refreshVoices;refreshVoices();}
function stopSpeech(){if(activeAudio){activeAudio.pause();activeAudio=null;audioFinish?.();audioFinish=null;}playToken++;inlinePlayback=null;document.querySelectorAll('.inline-formula').forEach(el=>el.remove());document.querySelectorAll('.inline-playing').forEach(el=>el.classList.remove('inline-playing'));playing=false;if('speechSynthesis'in window)speechSynthesis.cancel();$('playAll').textContent='▶ 全部听一遍';if($('batchBar'))$('batchBar').hidden=true;hidePictureRewards();syncModeControls();document.querySelectorAll('.is-current').forEach(c=>c.classList.remove('is-current'));highlightStep(-1);highlightPart('',-1);document.querySelectorAll('.reading-word').forEach(el=>el.classList.remove('reading-word'));clearFirework();}
function speakText(text,rate=Number($('rate').value),onStart=()=>{},light=false){return new Promise((resolve,reject)=>{if(!('speechSynthesis'in window)||!voiceList.length){reject(new Error('请先在设备设置中安装普通话语音，再重新打开网页。'));return;}const u=new SpeechSynthesisUtterance(text);u.lang='zh-CN';u.voice=voiceList[Number($('voice').value)]||voiceList[0];u.rate=light?Math.max(rate,1.05):rate;if(light)u.pitch=0.85;u.onstart=onStart;let timer=setTimeout(()=>{speechSynthesis.cancel();reject(new Error('语音没有响应，请在家长设置中换一个中文声音。'));},18000);u.onend=()=>{clearTimeout(timer);resolve();};u.onerror=e=>{clearTimeout(timer);if(e.error==='canceled'||e.error==='interrupted')resolve();else reject(new Error('朗读失败，请在家长设置中检查中文声音。'));};speechSynthesis.speak(u);});}
function charsFor(p){if(linkedWord(p))return linkedWord(p)[0];return p.split(' ').map(s=>{if(mapping[s])return mapping[s];throw new Error(`“${s}”暂缺可靠的示范字，请检查拼音或声调。`);}).join('，');}
async function readPinyin(p,token=playToken,onStart=()=>{}){try{const key=WORD_AUDIO[p]||audioAlias(p);if((!p.includes(' ')||WORD_AUDIO[p])&&localAudio.has(key))await playSound(key,onStart);else{if(!p.includes(' ')&&!tone(p))throw new Error('轻声请放在完整词语里听读，避免读成其他声调。');const text=charsFor(p);await speakText(text,Number($('rate').value),onStart);}if(token!==playToken)return false;seen.add(p);persist();render();return true;}catch(e){toast(e.message);return false;}}
function details(p){const sylls=p.split(' ');if(sylls.length>1)return{type:'词语练习',split:sylls.join(' · '),hint:'每个字先拼声母和韵母，再连起来读整个词语。整体认读和轻声单独练习。'};const base=plain(p);if(WHOLE.has(base))return{type:'整体认读音节',split:p,hint:'这是整体认读音节，记住整个读音，一口气读出来。'};const init=base.match(/^(zh|ch|sh|[bpmfdtnlgkhjqxzcsr])/);const sm=init?.[0]||'';let final=p.slice(sm.length);if(['j','q','x'].includes(sm)&&/^[uūúǔù]/.test(final))final='üǖǘǚǜ'['uūúǔù'.indexOf(final[0])]+final.slice(1);let parts=sm?[sm,final]:[p];if(sm&&/^[iuü][aeoāáǎàēéěèōóǒò]/.test(final))parts=[sm,final[0],final.slice(1)];let hint='听清读音，跟着慢慢读。';if(['zh','ch','sh','r'].includes(sm))hint='舌尖轻轻翘起来，再把后面的韵母连起来。';if(['z','c','s'].includes(sm))hint='舌尖放平，听清声母，再连起来读。';return{type:parts.length===3?'三拼音节':parts.length===2?'两拼音节':'韵母练习',split:parts.join(' — ')+' → '+p,hint,parts};}
function releaseRecording(){if(recorder&&recorder.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop());stream=null;clearTimeout(recordTimer);recording=false;$('record').textContent='🎤 我来读';}
function resetAudio(){releaseRecording();if(recordUrl)URL.revokeObjectURL(recordUrl);recordUrl=null;$('recording').pause();$('recording').removeAttribute('src');$('recording').hidden=true;}
function openLearn(i,continuing=false){if(!continuing)stopSpeech();else{clearFirework();hidePictureRewards();}resetAudio();checkMode=false;$('recordHint').textContent='先听示范，再录下来对照听';$('learn').classList.remove('checking');$('readingCheck').hidden=true;$('checkReading').textContent='自己读，检查一下 →';$('activeSyllable').hidden=true;for(const id of ['listen','spell','reveal','markRead','markUnknown'])$(id).disabled=false;selected=i;const p=items()[i];if(!p)return;const d=details(p);$('learnType').textContent=d.type;renderBigPinyin(p);renderLearnCharacter(p);$('toneInfo').textContent=p.split(' ').map(s=>{const t=tone(s);return `${s} · ${t?['','一声 · 平平的','二声 · 向上扬','三声 · 拐个弯','四声 · 落下来'][t]:'轻声 · 轻轻读'}`;}).join(' / ');renderFormula($('breakdown'),p,0);$('breakdown').hidden=p.includes(' ');renderWordSteps(p);$('listen').textContent='▶ 听一遍';$('mouth').textContent='';$('mouth').hidden=true;$('meaning').hidden=true;$('meaning').replaceChildren();$('reveal').textContent='认识对应汉字 ↓';$('spell').textContent='■ 停止';$('learnIndex').textContent=`${i+1} / ${items().length}`;$('previous').disabled=i===0;$('next').disabled=i===items().length-1;renderReviewHistory(p);syncMarkButtons(p);if(!$('learn').open)$('learn').showModal();syncModeControls();syncCharacterColors(p);$('learn').scrollTop=0;}
$('listen').onclick=()=>{if(checkMode)return;stopSpeech();playLesson(items()[selected],playToken);};
const INITIAL_CHARS={b:'波',p:'坡',m:'摸',f:'佛',d:'得',t:'特',n:'呢',l:'勒',g:'哥',k:'科',h:'喝',j:'鸡',q:'七',x:'西',zh:'知',ch:'吃',sh:'诗',r:'日',z:'资',c:'雌',s:'思'};
const INITIAL_SOUNDS={b:'bo1',p:'po1',m:'mo1',f:'fo2',d:'de1',t:'te4',n:'ne1',l:'le1',g:'ge1',k:'ke1',h:'he1',j:'ji1',q:'qi1',x:'xi1',zh:'zhi1',ch:'ch-callout-reference',sh:'shi1',r:'ri4',z:'zi1',c:'ci1',s:'si1'};
function spellingParts(p){const d=details(p);return (d.parts||[]).map((part,i)=>{const vowel=tone(part)?part:numbered(part+'1');return{key:i===0&&INITIAL_SOUNDS[part]?INITIAL_SOUNDS[part]:audioAlias(vowel),char:i===0&&INITIAL_CHARS[part]?INITIAL_CHARS[part]:mapping[vowel]||mapping[numbered(audioAlias(vowel).replace(/5$/,'0'))]};});}
function wordSteps(p){const chars=Array.from(linkedWord(p)?.[0]||'');return p.split(' ').map((syllable,i)=>{const d=details(syllable);return{syllable,char:chars[i]||'',formula:!tone(syllable)?syllable+' · 轻声':d.split,hint:!tone(syllable)?'放在词语里，轻轻读':d.type};});}
function highlightStep(index){document.querySelectorAll('.word-step').forEach((el,i)=>{el.classList.toggle('speaking',i===index);if(i===index)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');});}
function soundUnit(text,p,index,syllableIndex,kind){const span=document.createElement('span');span.className='sound-unit '+kind;span.dataset.pinyin=p;span.dataset.part=String(index);span.dataset.syllable=String(syllableIndex);span.textContent=text;return span;}
function renderFormula(box,p,syllableIndex){box.replaceChildren();const parts=details(p).parts;if(parts?.length>1){parts.forEach((part,i)=>{if(i)box.append(document.createTextNode(' — '));box.append(soundUnit(part,p,i,syllableIndex,i===0?'initial':'final'));});box.append(document.createTextNode(' → '));}box.append(soundUnit(p,p,-1,syllableIndex,'whole'));}
function renderBigPinyin(p){const box=$('bigPinyin');box.replaceChildren();p.split(' ').forEach((syllable,i)=>{if(i)box.append(document.createTextNode(' '));const button=document.createElement('button');button.className='syllable-tap';button.dataset.syllable=String(i);button.setAttribute('aria-label','点读 '+syllable);const parts=details(syllable).parts;if(parts?.length>1)parts.forEach((part,j)=>button.append(soundUnit(part,syllable,j,i,j===0?'initial':'final')));else button.append(soundUnit(syllable,syllable,-1,i,'whole'));button.onclick=()=>playTappedSyllable(p,i,button);box.append(button);});}
function highlightPart(p,index,syllableIndex=0){document.querySelectorAll('.sound-active,.character-active').forEach(el=>el.classList.remove('sound-active','character-active'));if(!p)return;const scope=inlinePlayback?findGridCard(inlinePlayback.p):$('learn');if(!scope)return;scope.querySelectorAll('.character-tap,.grid-glyph').forEach(el=>el.classList.toggle('character-active',Number(el.dataset.syllable||0)===syllableIndex));scope.querySelectorAll('.sound-unit').forEach(el=>{const same=el.dataset.pinyin===p&&Number(el.dataset.syllable)===syllableIndex;el.classList.toggle('sound-active',same&&(index===-1||Number(el.dataset.part)===index));});}
function renderWordSteps(p){const box=$('wordSteps');box.replaceChildren();box.hidden=!p.includes(' ');if(box.hidden)return;const hint=document.createElement('p');hint.className='word-step-hint';hint.textContent='点哪个字，就拼读哪个字';const row=document.createElement('div');row.className='word-step-row';for(const [i,step]of wordSteps(p).entries()){const button=document.createElement('button');button.className='word-step';button.dataset.syllable=step.syllable;button.setAttribute('aria-label','拼读第'+(i+1)+'个字 '+step.syllable);const py=document.createElement('b');const parts=details(step.syllable).parts;if(parts?.length>1)parts.forEach((part,j)=>py.append(soundUnit(part,step.syllable,j,i,j===0?'initial':'final')));else py.append(soundUnit(step.syllable,step.syllable,-1,i,'whole'));const char=document.createElement('span');char.className='step-character';char.textContent=step.char||'第'+(i+1)+'个音节';const formula=document.createElement('span');formula.className='step-formula';renderFormula(formula,step.syllable,i);const state=document.createElement('small');state.className='step-status';button.append(py,char,formula,state);button.onclick=()=>playTappedSyllable(p,i,button);row.append(button);}box.append(hint,row);refreshWordStepStates(p);}
let fireworkTimer,lastReward=null;
const READING_EFFECTS=[{name:'彩色烟花',kind:'fireworks',shapes:['✦','✧','●']},{name:'星星魔法',kind:'stars',shapes:['★','✦','✧']},{name:'花朵绽放',kind:'blossom',shapes:['🌸','✿','❀']},{name:'梦幻泡泡',kind:'bubbles',shapes:['○','◯','○']},{name:'彩虹光环',kind:'rainbow',shapes:['✦','●','✧']},{name:'流星飞舞',kind:'comets',shapes:['✦','✧','★']},{name:'爱心派对',kind:'hearts',shapes:['♥','♡','♥']},{name:'绿叶精灵',kind:'leaves',shapes:['🍃','🌿','✦']}];
function readingEffect(p,index){const syllable=p.split(' ')[index]||p;const char=Array.from(linkedWord(p)?.[0]||displayedHanzi(p)||'')[index]||syllable;const seed=Array.from(char+syllable).reduce((n,c)=>(n*31+c.codePointAt(0))>>>0,17);const special={树:7,枝:2,花:2,水:3,雨:3,泡:3,星:1,天:4,虹:4,爱:6,心:6,火:0,日:0,月:5,纸:1,折:0,苹:6,果:3};return{...READING_EFFECTS[special[char]??seed%READING_EFFECTS.length],seed,char,hue:seed%360};}
function clearFirework(){clearTimeout(fireworkTimer);lastReward=null;document.querySelectorAll('.letter-celebration').forEach(el=>el.remove());document.querySelectorAll('.rewarding').forEach(el=>el.classList.remove('rewarding'));document.querySelectorAll('.has-reward').forEach(el=>el.classList.remove('has-reward'));$('firework')?.replaceChildren();}
function rewardAnchor(target){return target?.matches('.word-step')?target.querySelector('.step-character'):target?.matches('.sound')?target.querySelector('.card-hanzi')||target.querySelector('.pinyin'):target;}
function rewardTargets(p,target,whole){const anchor=rewardAnchor(target);if(whole&&target?.matches('.sound')){const glyphs=[...target.querySelectorAll('.grid-glyph')];return glyphs.length?glyphs:[...target.querySelectorAll('.pinyin-syllable')];}if(!whole)return[anchor||$('learnCharacter').querySelector('.character-tap')||$('bigPinyin').querySelector('.syllable-tap')];const selector=target?.matches('.word-step')?'#wordSteps .step-character':target?.matches('.syllable-tap')?'#bigPinyin .syllable-tap':'#learnCharacter .character-tap';const targets=[...document.querySelectorAll(selector)];return targets.length?targets:[...$('bigPinyin').querySelectorAll('.syllable-tap')];}
function burstOnLetter(anchor,effect,delay=0,picture=null){if(!anchor)return;anchor.closest('.card')?.classList.add('has-reward');anchor.classList.add('rewarding');const burst=document.createElement('span');burst.className='letter-celebration effect-'+effect.kind+(picture?' image-particles':'');if(picture)burst.dataset.picture=picture.graphic;burst.setAttribute('aria-hidden','true');burst.style.setProperty('--hue',effect.hue);burst.style.setProperty('--effect-delay',delay+'ms');const halo=document.createElement('span');halo.className='reward-halo';burst.append(halo);const shapes=picture?picturePieces(picture.graphic):effect.shapes;const count=picture?18:effect.kind==='fireworks'?32:20;for(let i=0;i<count;i++){const particle=document.createElement('i');const angle=(i/count*Math.PI*2)+(effect.seed%30)*Math.PI/180;const radius=64+(i%4)*15;particle.textContent=shapes[i%shapes.length];particle.style.setProperty('--x',Math.cos(angle)*radius+'px');particle.style.setProperty('--y',Math.sin(angle)*radius+'px');particle.style.setProperty('--spin',((i%2?-1:1)*(70+i*13))+'deg');particle.style.setProperty('--color','hsl('+((effect.hue+i*43)%360)+' 85% 61%)');particle.style.setProperty('--particle-delay',(delay+(i%4)*35)+'ms');particle.style.setProperty('--size',(picture?26+i%3*6:effect.kind==='bubbles'?23+i%3*7:17+i%3*5)+'px');burst.append(particle);}anchor.append(burst);}
function picturePieces(graphic){if(typeof Intl.Segmenter==='function')return Array.from(new Intl.Segmenter('zh',{granularity:'grapheme'}).segment(graphic),x=>x.segment).filter(x=>x.trim());return Array.from(graphic).filter(x=>!/[\uFE0F\u200D]/.test(x));}
function chooseReadingReward(p,random=Math.random){const picture=pictureFor(p);if(picture.matched)return{kind:'matched',picture,effect:null};return random()<0.5?{kind:'stars',picture:{...picture,graphic:'🌟⭐'},effect:READING_EFFECTS[1]}:{kind:'fireworks',picture:null,effect:READING_EFFECTS[0]};}
function celebrateReading(token,p,index=0,target=null,whole=false){if(token!==playToken||checkMode||(!$('learn').open&&!target))return;clearFirework();const targets=rewardTargets(p,target,whole);const anchor=whole?(target?.matches('.sound')?target.querySelector('.card-hanzi')||target.querySelector('.pinyin'):$('learnCharacter').querySelector('strong')||$('bigPinyin')):targets[0];const choice=chooseReadingReward(p);lastReward={...choice,p,token};burstOnLetter(anchor,{...readingEffect(p,index),...(choice.effect||{})},0,choice.picture);$('firework').textContent=whole?'整词听完啦！':'“'+readingEffect(p,index).char+'”听完啦！';fireworkTimer=setTimeout(clearFirework,2400);}
async function finishWord(p,token){if(token!==playToken)return false;highlightStep(-1);highlightPart('',-1);const glyph=inlinePlayback?findGridCard(p)?.querySelector('.card-hanzi'):$('learnCharacter');glyph?.classList.add('reading-word');try{return await readPinyin(p,token);}finally{if(token===playToken)glyph?.classList.remove('reading-word');}}
async function playTappedSyllable(p,index,target=null){if(checkMode)return;stopSpeech();const token=playToken,syllables=p.split(' ');highlightStep(p.includes(' ')?index:-1);try{const ok=await spellSyllable(syllables[index],token,p,index);if(!ok||token!==playToken)return;markCharacterHeard(p,index);const whole=index===syllables.length-1;if(whole&&(!await componentPause(token)||!await finishWord(p,token)))return;if(whole){celebrateReading(token,p,index,target,syllables.length>1);showPictureReward(p,token);}}catch(e){toast(e.message);}finally{if(token===playToken){highlightStep(-1);highlightPart('',-1);}}}
function refreshWordStepStates(word){if(!word?.includes(' '))return;document.querySelectorAll('.word-step').forEach((button,index)=>{const syllable=word.split(' ')[index];if(button.dataset.syllable!==syllable)return;const wordReview=visibleReview(word);let review=visibleReview(syllable);if(wordReview?.independent===true&&wordReview.answers?.[index])review={independent:true,passed:assessmentCriteria(syllable).every(c=>wordReview.answers[index][c.id]===true)};const state=readingState(hasHeardCharacter(word,index),review,manualMarks[syllable]);for(const name of ['new','heard','passed','practice','read','unknown'])button.classList.toggle('status-'+name,state===name);const label=button.querySelector('.step-status');if(label)label.textContent={new:'未听',heard:'已听 · 未评分',passed:'✓ 家长确认读对',practice:'↻ 还需练习',read:'✓ 已读',unknown:'不会 · 再练练'}[state];});}
async function componentPause(token){if(token!==playToken)return false;await new Promise(resolve=>setTimeout(resolve,180));return token===playToken;}
async function spellSyllable(p,token,word='',syllableIndex=0){if(token!==playToken)return false;const illuminate=index=>()=>{if(token===playToken)highlightPart(p,index,syllableIndex);};if(!tone(p)&&word){const character=wordSteps(word)[syllableIndex]?.char;if(!character){toast('请先为这个轻声音节补上对应汉字。');return false;}await speakText(character,Number($('rate').value),illuminate(-1),true);if(token!==playToken)return false;seen.add(p);persist();render();return true;}const d=details(p);if(d.parts?.length>1){for(const [index,part]of spellingParts(p).entries()){if(token!==playToken)return false;if(localAudio.has(part.key))await playSound(part.key,illuminate(index));else if(part.char)await speakText(part.char,0.7,illuminate(index));else{toast('这个音节暂未配置拆分示范，先听完整读音吧。');break;}if(token!==playToken)return false;highlightPart('',-1);if(!await componentPause(token))return false;}}if(token!==playToken)return false;return await readPinyin(p,token,illuminate(-1));}
async function playLesson(p,token,surface=null){if(token!==playToken||checkMode)return false;try{const steps=wordSteps(p);for(const [i,step]of steps.entries()){if(token!==playToken)return false;highlightStep(p.includes(' ')?i:-1);if(surface)inlineFormula(surface,step.syllable,i);if(!await spellSyllable(step.syllable,token,p,i)||token!==playToken)return false;markCharacterHeard(p,i);}if(!await componentPause(token)||!await finishWord(p,token))return false;celebrateReading(token,p,p.split(' ').length-1,surface,p.includes(' '));showPictureReward(p,token,surface?'deskReward':'pictureReward');return token===playToken;}catch(e){toast(e.message);return false;}finally{if(token===playToken){highlightStep(-1);highlightPart('',-1);}}}
