$('reveal').onclick=()=>{if(checkMode)return;const p=items()[selected],box=$('meaning');if(!box.hidden){box.hidden=true;return;}const word=linkedWord(p);const strong=document.createElement('strong');strong.textContent=displayedHanzi(p)||'暂未配置';const small=document.createElement('small');small.textContent=recognizedWords[p]?.source==='image'?'图片中的汉字，已由家长校对。':recognizedWords[p]?.source==='manual'?'家长录入并确认的字词。':'帮助记音的示例字词，同音字可能还有其他写法。';box.replaceChildren(strong,small);box.hidden=false;};
function syncModeControls(){for(const suffix of ['', 'Inside']){const teach=$('teachMode'+suffix),fast=$('quickMode'+suffix);teach?.setAttribute('aria-pressed',String(playing||!quickMode));fast?.setAttribute('aria-pressed',String(quickMode&&!playing));}if($('gridHint'))$('gridHint').textContent=quickMode?'快速模式：在卡片上直接拼读，再读中文':'点卡片开始，点字听拼读';if($('learn').open){const p=items()[selected];$('tapHint').textContent=playing?'正在完整连播 · 声母、韵母、音节，最后读中文':quickMode?'快速模式 · 声母、韵母拼读，最后读中文':'点一个字，听拼读 · 最后一个读完，再读中文';}document.body.classList.toggle('quick-mode',quickMode&&!playing);document.querySelectorAll('.word-step-hint').forEach(el=>el.textContent='点哪个字，就拼读哪个字');}
