async function quickReadCard(p,target){if(!items().includes(p))return false;stopSpeech();checkMode=false;const token=playToken,card=findGridCard(p),surface=card?.querySelector('.sound')||target;if(!surface)return false;inlinePlayback={p,token};card?.classList.add('inline-playing');try{return await playLesson(p,token,surface);}finally{if(inlinePlayback?.token===token){inlinePlayback=null;card?.classList.remove('inline-playing');surface.querySelector('.inline-formula')?.remove();refreshGridStates();}}}
