function pictureFor(p){const hanzi=linkedWord(p)?.[0]||mapping[p]||'';return{hanzi,graphic:WORD_PICTURES[hanzi]||WORDS[p]?.[1]||'🌟',matched:!!(WORD_PICTURES[hanzi]||WORDS[p]?.[1])};}
function showPictureReward(p,token,id='pictureReward'){if(token!==playToken||checkMode)return;const box=$(id);if(!box)return;const picture=pictureFor(p);const fireworks=!picture.matched&&lastReward?.p===p&&lastReward.token===token&&lastReward.kind==='fireworks';box.replaceChildren();const art=document.createElement('span');art.className='reward-art';art.setAttribute('role','img');art.setAttribute('aria-label',picture.matched?picture.hanzi+'的图案':fireworks?'奖励烟花':'奖励星星');art.textContent=fireworks?'🎆':picture.graphic;const copy=document.createElement('div');const title=document.createElement('strong');title.textContent=picture.matched?'送你一张“'+picture.hanzi+'”小贴纸！':fireworks?'送你一朵彩色烟花！':'送你一颗奖励星星！';const hint=document.createElement('small');hint.textContent='又完成一次点读，继续加油！';copy.append(title,hint);box.append(art,copy);box.hidden=false;if(id==='pictureReward')box.scrollIntoView({block:'nearest',behavior:'auto'});}
async function playAllLessons(){if(playing){stopSpeech();return;}stopSpeech();const token=playToken,list=[...items()];playing=true;$('playAll').textContent='■ 停止播放';try{for(let i=0;i<list.length;i++){if(token!==playToken)return;openLearn(i,true);$('batchBar').hidden=false;$('batchStatus').textContent='完整拼读 · '+(i+1)+' / '+list.length;if(!await playLesson(list[i],token))return;if(i<list.length-1){await new Promise(resolve=>setTimeout(resolve,2200));if(token!==playToken)return;}}}finally{if(token===playToken){playing=false;$('playAll').textContent='▶ 全部听一遍';$('batchBar').hidden=true;syncModeControls();}}}
