$('record').onclick=async()=>{if(recording){releaseRecording();return;}stopSpeech();if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('当前浏览器不支持录音，请使用最新版 Safari 或 Chrome。');return;}try{$('record').disabled=true;resetAudio();const requestedP=items()[selected];stream=await navigator.mediaDevices.getUserMedia({audio:true});if(!$('learn').open||requestedP!==items()[selected]){releaseRecording();return;}const chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{if(chunks.length){recordUrl=URL.createObjectURL(new Blob(chunks,{type:chunks[0].type}));$('recording').src=recordUrl;$('recording').hidden=false;}};recorder.start();recording=true;$('record').textContent='■ 停止录音';recordTimer=setTimeout(()=>{releaseRecording();toast('录音完成，听听自己的声音吧。');},15000);}catch(e){releaseRecording();toast(e.name==='NotAllowedError'?'麦克风未获允许，请在浏览器设置中开启权限。':'无法使用麦克风，请检查设备。');}finally{$('record').disabled=false;}};
