function parseLearningDraft(text){const lines=text.split(/\n+/).map(s=>s.trim()).filter(Boolean);if(!lines.length)throw new Error('请先输入拼音或汉字。');if(lines.length>150)throw new Error('一次最多150项，请分批添加。');const keys=[],characters={};for(const [i,line]of lines.entries()){let [py,hanzi='']=line.split(/[|｜]/).map(s=>s.trim());if(/^[\u3400-\u9fff]{1,8}$/.test(py)&&!hanzi){hanzi=py;py=Object.entries(WORDS).find(([,value])=>value[0]===hanzi)?.[0]||pinyinPro.pinyin(hanzi);}py=numbered(py).replace(/\s+/g,' ');if(hanzi&&!/^[\u3400-\u9fff]{1,8}$/.test(hanzi))throw new Error('第'+(i+1)+'行的汉字格式不正确。');if(hanzi&&Array.from(hanzi).length!==py.split(' ').length)throw new Error('第'+(i+1)+'行的汉字数量与音节数量不同，请核对。');if(py.split(' ').some(s=>!bases.has(plain(s))||(tone(s)>0&&!mapping[s]&&!localAudio.has(audioAlias(s)))))throw new Error('请核对第'+(i+1)+'行的拼音和声调：'+py);if(!keys.includes(py))keys.push(py);if(hanzi){const source=pendingRecognition?.items.find(x=>x.pinyin===py&&x.hanzi===hanzi)?.source||(recognizedWords[py]?.hanzi===hanzi?recognizedWords[py].source:'manual');if(characters[py]&&characters[py].hanzi!==hanzi){characters[py].alternatives=[...new Set([...(characters[py].alternatives||[]),hanzi])];}else if(!characters[py])characters[py]={hanzi,source,confirmed:true};}}return{keys,characters};}
$('saveDraft').onclick=()=>{try{const parsed=parseLearningDraft($('draft').value);lesson={title:pendingRecognition?.title||'我的识字作业',syllables:parsed.keys.filter(x=>!x.includes(' ')),words:parsed.keys.filter(x=>x.includes(' ')),characters:parsed.characters};recognizedWords=parsed.characters;seen=new Set();persist();$('editor').close();setTab(lesson.syllables.length?'syllables':'words');toast('字、词和拼音准备好了，点开就能读。');}catch(error){$('draftError').textContent=error.message;}};
function renderLearnCharacter(p){const box=$('learnCharacter');box.replaceChildren();const text=displayedHanzi(p);box.hidden=!text;if(!text)return;const glyph=document.createElement('strong');if(!p.includes(' ')){const button=document.createElement('button');button.className='character-tap';button.textContent=text;button.setAttribute('aria-label','点读汉字 '+text);button.onclick=()=>playTappedSyllable(p,0,button);glyph.append(button);}else {Array.from(linkedWord(p)?.[0]||text).forEach((char,i)=>{const button=document.createElement('button');button.className='character-tap';button.dataset.syllable=String(i);button.textContent=char;button.setAttribute('aria-label','点读汉字 '+char);button.onclick=()=>playTappedSyllable(p,i,button);glyph.append(button);});}const source=document.createElement('small');source.textContent=recognizedWords[p]?.source==='image'?'图片原字 · 已校对':recognizedWords[p]?.source==='manual'?'家长录入':'配套示例字词';box.append(glyph,source);}
function renderRecognitionNotes(result){const box=$('recognitionNotes');box.replaceChildren();const summary=document.createElement('strong');summary.textContent='DeepSeek 已识别 '+result.items.length+' 项'+(result.needsReview?' · '+result.needsReview+' 项需重点核对':'');box.append(summary);for(const entry of result.items.filter(x=>x.uncertain)){const line=document.createElement('p');line.textContent='⚠ '+entry.pinyin+(entry.hanzi?' | '+entry.hanzi:'')+'：'+(entry.note||'请核对声调和对应字。');box.append(line);}}
async function preparePhoto(file){const img=new Image();const src=URL.createObjectURL(file);try{img.src=src;await img.decode();const toImage=(x,y,w,h,max=1500)=>{const scale=Math.min(1,max/Math.max(w,h)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(w*scale));canvas.height=Math.max(1,Math.round(h*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,x,y,w,h,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',0.88);};const images=[toImage(0,0,img.width,img.height,1600)];if(Math.max(img.width,img.height)>=900){if(img.height>=img.width*0.75){const h=Math.ceil(img.height*0.55);images.push(toImage(0,0,img.width,h),toImage(0,img.height-h,img.width,h));}else{const w=Math.ceil(img.width*0.55);images.push(toImage(0,0,w,img.height),toImage(img.width-w,0,w,img.height));}}return images;}finally{URL.revokeObjectURL(src);}}
$('file').onchange=async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;const requestKey=apiKeys.get();if(!requestKey){openApiSettings(true);return;}if(ocrBusy){toast('上一张照片还在识别，请稍候。');return;}if(file.size>12*1024*1024){toast('请选择小于12 MB的照片。');return;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('请选择 JPG、PNG 或 WebP 照片。');return;}if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl=URL.createObjectURL(file);photo=photoUrl;editor(true);ocrBusy=true;$('saveDraft').disabled=true;$('ocrStatus').textContent='正在准备照片…';try{const images=await preparePhoto(file);$('ocrStatus').textContent='DeepSeek 正在看照片，识别汉字、拼音和词语…';const response=await fetch('/api/recognize',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({images,apiKey:requestKey}),signal:AbortSignal.timeout(65000)});let result;try{result=await response.json();}catch{throw new Error('识别服务暂时无法连接，请稍后重试。');}if(!response.ok){if(result.code==='invalid_api_key'||result.code==='missing_api_key')openApiSettings(false,result.error);throw new Error(result.error||'识别暂时失败，请稍后再试。');}if(!Array.isArray(result.items)||!result.items.length)throw new Error('没有识别到内容，请重新拍照。');pendingRecognition=result;$('draft').value=result.items.flatMap(item=>[item.pinyin+(item.hanzi?' | '+item.hanzi:''),...(item.alternatives||[]).map(hanzi=>item.pinyin+' | '+hanzi)]).join('\n');renderRecognitionNotes(result);$('ocrStatus').textContent='请对照原图确认声调和对应字。图片只有拼音时，配字属于示例，不是原图答案。';}catch(error){$('ocrStatus').textContent=error.name==='TimeoutError'?'识别超时，请重新上传，或对照原图手动输入。':error.message+' 也可以对照原图手动输入。';}finally{ocrBusy=false;$('saveDraft').disabled=false;}};
$('editor').addEventListener('cancel',e=>{if(ocrBusy){e.preventDefault();toast('DeepSeek 正在识别照片，请稍候。');}});
$('clear').onclick=()=>{stopSpeech();lesson=structuredClone(SAMPLE);recognizedWords={};favorites=[];seen=new Set();reviews={};manualMarks={};characterHeard={};clearedColors=new Set();photo='sample.png';if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl=null;persist();$('settings').close();setTab('syllables');toast('已清除本机记录，恢复示例练习。');};

function renderReviewHistory(p){const review=reviews[p],grade=reviewGrade(p,review);$('reviewHistory').textContent=review?'家长检查 '+(grade?grade.score+' 分（'+grade.earned+'/'+grade.total+'项） · ':'')+new Date(review.at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})+' · '+(review.passed?'本次独立读对':'还需练习'):'尚未评分：听过示范不会自动得分。';}
function startReadingCheck(){stopSpeech();resetAudio();checkMode=true;$('recordHint').textContent='看拼音自己读，可录下来供家长回放';$('learn').classList.add('checking');$('readingCheck').hidden=false;$('checkReading').textContent='← 返回听读教学';$('activeSyllable').hidden=true;$('meaning').hidden=true;for(const id of ['listen','spell','reveal','markRead','markUnknown'])$(id).disabled=true;const p=items()[selected];$('checkRows').replaceChildren();for(const [i,syllable]of p.split(' ').entries()){const row=document.createElement('fieldset');row.className='check-row';const title=document.createElement('legend');title.textContent=(i+1)+' · '+syllable;row.append(title);for(const criterion of assessmentCriteria(syllable)){const label=document.createElement('label');label.className='check-option';const input=document.createElement('input');input.type='checkbox';input.dataset.syllable=String(i);input.dataset.criterion=criterion.id;input.setAttribute('aria-label',syllable+' '+criterion.label);label.append(input,document.createTextNode(criterion.label));row.append(label);}$('checkRows').append(row);}$('joinedRow').hidden=!p.includes(' ');$('joinedReading').checked=false;$('independentReading').checked=false;$('readingCheckResult').textContent='';$('readingCheck').scrollIntoView({behavior:'smooth',block:'start'});}
$('checkReading').onclick=()=>{if(!checkMode){startReadingCheck();return;}stopSpeech();resetAudio();checkMode=false;$('recordHint').textContent='先听示范，再录下来对照听';$('learn').classList.remove('checking');$('readingCheck').hidden=true;$('checkReading').textContent='自己读，检查一下 →';for(const id of ['listen','spell','reveal','markRead','markUnknown'])$(id).disabled=false;};
$('saveReadingCheck').onclick=()=>{if(!checkMode)return;const p=items()[selected];if(!$('independentReading').checked){$('readingCheckResult').textContent='请先让孩子不听示范独立读，再由家长确认已听过这次朗读。';return;}const answers=p.split(' ').map(()=>({}));for(const input of $('checkRows').querySelectorAll('input'))answers[Number(input.dataset.syllable)][input.dataset.criterion]=input.checked;const result=evaluateReading(p,answers,$('joinedReading').checked,true);reviews[p]={at:Date.now(),source:'parent',independent:true,answers,joined:$('joinedReading').checked,passed:result.passed,score:result.score,earned:result.earned,total:result.total};delete manualMarks[p];clearedColors.delete(p);persist();syncMarkButtons(p);render();renderReviewHistory(p);$('readingCheckResult').textContent='家长检查得分：'+result.score+' 分（'+result.earned+'/'+result.total+' 项）。'+(result.passed?'家长已确认：本次独立读对。建议隔天再读一次。':'已记为还需练习：'+result.missing.slice(0,4).join('；')+(result.missing.length>4?'等':'')+'。');};


function syncMarkButtons(p){const mark=manualMarks[p];$('markRead').setAttribute('aria-pressed',String(mark==='read'));$('markUnknown').setAttribute('aria-pressed',String(mark==='unknown'));$('manualStatus').textContent=mark==='read'?'已标记：已读':mark==='unknown'?'已标记：不会，再练练':'';}
function setManualMark(mark){if(checkMode)return;const p=items()[selected];if(!p)return;stopSpeech();manualMarks[p]=mark;if(mark==='read')seen.add(p);persist();render();syncMarkButtons(p);}
$('markRead').onclick=()=>setManualMark('read');
$('markUnknown').onclick=()=>setManualMark('unknown');

window.addEventListener('pagehide',()=>{stopSpeech();releaseRecording();});render();
